\title{AoI-Aware V2I Uplink Scheduling via Deep Reinforcement Learning with Hybrid Action Space}

\author{Youngju~Nam,~Dick~Mugerwa,~Yongje~Shin,~Jeong-Hun~Kim,~and~Euisin~Lee,~\IEEEmembership{}%
